    cambia = "El vocabulario que usar\u00e1n los modelos. No cambia los recuentos de autores, revistas o a\u00f1os del paso 03.",
    comprobar = "Mira qu\u00e9 palabras perder\u00edas y abre un par de documentos donde aparec\u00edan. Comprueba que ning\u00fan documento se quede sin vocabulario.",
    ejemplo = "Con 100 documentos, una palabra que sale en uno solo se elimina con valor 2. Con valor 1 se conserva, aunque quiz\u00e1 sea una errata.",
    tecnica = "Frecuencia documental m\u00ednima (df): n\u00famero de documentos distintos con la palabra. Una palabra repetida muchas veces en un solo documento tiene df = 1."),
  max_df_pct = list(pregunta = "\u00bfQuieres retirar las palabras que aparecen en casi todos los documentos?",
