    ejemplo = "Una palabra repetida 30 veces en un solo documento destaca por \u00abse repite m\u00e1s\u00bb, pero aparece en 1 documento de 100 y no por \u00abaparece en m\u00e1s documentos\u00bb.",
    tecnica = "Presencia documental (df), frecuencia total y TF-IDF medio global. Otros res\u00famenes del peso (mediana, percentiles) est\u00e1n en la lista avanzada y pueden valer cero."),
  network_weight = list(pregunta = "\u00bfC\u00f3mo quieres que pese cada conexi\u00f3n?",
    empezar = "Para palabras, empieza con \u00abFuerza de asociaci\u00f3n\u00bb: evita que las palabras muy frecuentes dominen. Para autores, \u00abCompleto\u00bb cuenta documentos compartidos.",
    cambiar = "Prueba \u00abCoseno\u00bb si quieres comparar con otra normalizaci\u00f3n, y comprueba si las conexiones fuertes se mantienen.",
    cambia = "El grosor y el orden de las conexiones, y con ello las comunidades. No cambia qu\u00e9 nodos est\u00e1n ni los documentos.",
    comprobar = "Cambia el peso y observa si las mismas parejas siguen entre las m\u00e1s fuertes. Si no, esa conclusi\u00f3n depende de la medida.",
    ejemplo = "Dos palabras que aparecen en 40 de 50 documentos se juntan siempre; la fuerza de asociaci\u00f3n les da menos peso que a dos palabras raras que casi siempre coinciden.",
    tecnica = "Fuerza de asociaci\u00f3n: coincidencias / (presencia A \u00d7 presencia B). Es una normalizaci\u00f3n por presencia, no una prueba estad\u00edstica: no ofrece valores p."),
  wiki_concept_k = list(pregunta = "\u00bfCu\u00e1ntas relaciones debe conservar cada palabra en el dibujo?",
    empezar = "Conserva 3: el grafo se lee bien y cada palabra mantiene sus conexiones m\u00e1s fuertes. Con 0 se conservan todas, aunque el dibujo se sature.",
    cambiar = "S\u00fabelo si te faltan conexiones que te interesan; b\u00e1jalo si el dibujo es una mara\u00f1a.",
    cambia = "La red que se analiza: se aplica antes de calcular comunidades y roles, as\u00ed que otro valor puede dar otras comunidades.",
    comprobar = "Repite con otro valor y mira si las comunidades principales se mantienen. Una palabra puede tener m\u00e1s l\u00edneas que este n\u00famero.",
    ejemplo = "Con valor 1, una palabra central rodeada de cuatro palabras que la eligen se queda con cuatro l\u00edneas, aunque su l\u00edmite sea una.",
    tecnica = "Se conserva la uni\u00f3n de las k relaciones m\u00e1s fuertes por Jaccard de cada palabra; no es una prueba estad\u00edstica."),
  lda_k = list(pregunta = "\u00bfCu\u00e1ntos temas quieres buscar?",
    empezar = "Compara varios valores con la comparaci\u00f3n de soluciones y elige dos o tres candidatos. No hay un n\u00famero correcto que el programa pueda decidir.",
    cambiar = "Aumenta k si un tema mezcla ideas claramente distintas; red\u00facelo si dos temas son casi iguales.",
    cambia = "El modelo entero: las palabras y proporciones de cada tema cambian al cambiar k.",
    comprobar = "Lee las palabras principales y varios documentos de cada tema. Qu\u00e9date con el k cuyos temas puedas nombrar y defender.",
    ejemplo = "Con k = 3, un tema puede juntar \u00abaprendizaje\u00bb y \u00abevaluaci\u00f3n\u00bb; con k = 5 esos asuntos pueden separarse. Ninguno es verdadero: se leen y se comparan.",
    tecnica = "LDA con muestreo de Gibbs. La comparaci\u00f3n resume coherencia, diversidad, estabilidad y perplejidad; ning\u00fan criterio decide por s\u00ed solo."),
  jsd_weight = list(pregunta = "\u00bfQuieres que los textos largos pesen m\u00e1s o que todos pesen igual?",
    empezar = "Elige \u00abTokens agrupados\u00bb para comparar el reparto de todas las palabras; elige \u00abDocumentos equilibrados\u00bb para comparar el perfil medio de las publicaciones.",
    cambiar = "Cambia a documentos equilibrados cuando unos pocos textos muy largos podr\u00edan dominar la comparaci\u00f3n.",
    cambia = "La pregunta que responde la comparaci\u00f3n: una direcci\u00f3n de barra puede invertirse sin que ninguna cuenta est\u00e9 mal.",
    comprobar = "Repite con la otra opci\u00f3n si la longitud de los textos puede cambiar tu lectura y conserva ambos resultados.",
    ejemplo = "Una revisi\u00f3n de 10.000 palabras que repite un t\u00e9rmino domina con tokens agrupados, pero pesa lo mismo que un resumen corto con documentos equilibrados.",
    tecnica = "Tokens agrupados: se suman las palabras del grupo. Documentos equilibrados: se promedian las proporciones de cada documento."),
  hdb_min_pts = list(pregunta = "\u00bfQu\u00e9 tama\u00f1o m\u00ednimo debe tener un grupo de documentos parecidos?",
    empezar = "Empieza con 5 y compara con 10. Un valor mayor exige grupos m\u00e1s grandes y deja m\u00e1s documentos sin asignar.",
    cambiar = "S\u00fabelo si salen muchos grupos diminutos; b\u00e1jalo si casi todos los documentos quedan sin asignar.",
    cambia = "En esta aplicaci\u00f3n un solo valor (minPts) fija a la vez el tama\u00f1o m\u00ednimo del grupo y la densidad que se exige.",
    comprobar = "Mira cu\u00e1ntos documentos quedan sin asignar y lee varios documentos de cada grupo. Cambia la semilla para ver si los grupos se mantienen.",
    ejemplo = "Con 60 documentos y minPts = 5 pueden salir cuatro grupos y 12 documentos sin asignar; con minPts = 10, dos grupos y 25 sin asignar.",
    tecnica = "HDBSCAN con minPts \u00fanico. UMAP es aleatorio: la semilla importa y HDBSCAN es determinista con las mismas coordenadas."),
  split_sentences = list(pregunta = "\u00bfAnalizas documentos completos o frases?",
    empezar = "Usa documentos completos: es lo m\u00e1s f\u00e1cil de leer y de explicar. Las frases solo interesan si cada resumen mezcla asuntos distintos.",
    cambiar = "Activa las frases si quieres detectar temas dentro de un mismo documento, sabiendo que habr\u00e1 m\u00e1s unidades y m\u00e1s c\u00e1lculo.",
    cambia = "La unidad de LDA y correspondencias. UMAP, HDBSCAN y ACP siempre usan documentos.",
    comprobar = "Comprueba cu\u00e1ntas unidades quedan sin palabras tras la limpieza y que los resultados se leen mejor, no solo que son m\u00e1s numerosos.",
    ejemplo = "Un resumen de cinco frases se convierte en cinco unidades; un tema que ocupa dos de ellas aparece en proporci\u00f3n dentro del documento.",
    tecnica = "Con frases, el peso se resume sobre frases con palabras tras la limpieza; la presencia m\u00ednima sigue contando documentos.")
)

decision_help_fields <- c("pregunta", "empezar", "cambiar", "cambia", "comprobar", "ejemplo", "tecnica")

# Ficha plegada junto al control. Muestra la pregunta y la recomendación inicial; el resto se despliega.
decision_card <- function(id) {
  h <- decision_help_catalog()[[id]]
  if (is.null(h)) return(NULL)
  htmltools::tags$details(class = "decision-card",
    htmltools::tags$summary(h$pregunta),
    htmltools::tags$p(htmltools::tags$strong("Para empezar: "), h$empezar),
    htmltools::tags$p(htmltools::tags$strong("Cu\u00e1ndo cambiarlo: "), h$cambiar),
    htmltools::tags$p(htmltools::tags$strong("Qu\u00e9 cambia: "), h$cambia),
    htmltools::tags$p(htmltools::tags$strong("Qu\u00e9 comprobar: "), h$comprobar),
    htmltools::tags$p(htmltools::tags$strong("Ejemplo ilustrativo: "), h$ejemplo),
    htmltools::tags$details(class = "decision-technical", htmltools::tags$summary("C\u00f3mo se calcula"), htmltools::tags$p(h$tecnica)))
}
